"use client";

import {
    useEffect,
    useRef,
    useState,
    type ReactNode,
    type WheelEvent,
    type TouchEvent,
} from "react";
import { motion } from "framer-motion";
import { manualControl } from "@/lib/api/droneCommand";
import { Spinner } from "@/components/ui/spinner";

/**
 * Optional live-telemetry shape. Pass this in from MapView (droneTelemetryData[droneId])
 * so the panel shows real lat/lng/alt/heading instead of placeholders.
 * Everything is optional so this component still works if the caller only
 * passes droneId / currentAltitude / onClose, exactly like the old panel.
 */
type DroneTelemetryLite = {
    lat?: number | null;
    lng?: number | null;
    alt?: number | null;
    heading?: number | null;
    status?: string | null;
};

interface DroneControllerProps {
    droneId: string;
    currentAltitude?: number;
    onClose: () => void;
    telemetry?: DroneTelemetryLite | null;
    /**
     * "modal" (default) — the original draggable floating panel, used when
     * MapView renders this inline over the map.
     * "page" — a full-page layout with no drag/fixed-positioning, used when
     * this component is rendered as its own route (e.g. /drones/[id]/control).
     */
    variant?: "modal" | "page";
    /** Optional label shown in the page header (variant="page" only). */
    droneName?: string;
    /** Optional live socket status badge (variant="page" only). */
    socketConnected?: boolean;
}

const FLIGHT_MODES = ["RTL", "ALT Hold", "Loiter", "Auto"] as const;
type FlightMode = (typeof FLIGHT_MODES)[number];

const MODE_COMMAND: Record<FlightMode, string> = {
    RTL: "SET_MODE_RTL",
    "ALT Hold": "SET_MODE_ALT_HOLD",
    Loiter: "SET_MODE_LOITER",
    Auto: "SET_MODE_AUTO",
};

const CORRECT_DROP_PIN = "1234";

export default function DroneController({
    droneId,
    currentAltitude = 0,
    onClose,
    telemetry = null,
    variant = "modal",
    droneName,
    socketConnected,
}: DroneControllerProps) {
    const isPage = variant === "page";
    const [activeMode, setActiveMode] = useState<FlightMode | null>(null);
    const [altitude, setAltitude] = useState<number>(currentAltitude);
    const [activeDirection, setActiveDirection] = useState<string | null>(null);
    const [isSending, setIsSending] = useState(false);

    // ── Heading / compass ──────────────────────────────────────────────
    const [heading, setHeading] = useState<number>(telemetry?.heading ?? 0);
    const headingRef = useRef(heading);
    useEffect(() => {
        headingRef.current = heading;
    }, [heading]);

    // If live telemetry heading updates and the user isn't mid-drag, sync the dial to it.
    const isDraggingCompass = useRef(false);
    useEffect(() => {
        if (!isDraggingCompass.current && typeof telemetry?.heading === "number") {
            setHeading(telemetry.heading);
        }
    }, [telemetry?.heading]);

    useEffect(() => {
        if (typeof telemetry?.alt === "number") {
            setAltitude(telemetry.alt);
        }
    }, [telemetry?.alt]);

    // ── Video feed (placeholder, wire up RTSP/WebRTC source later) ─────
    const videoRef = useRef<HTMLVideoElement | null>(null);
    const videoSrc = "";
    const [feedStatus, setFeedStatus] = useState<"idle" | "loading" | "ready" | "error">("idle");
    const [feedError, setFeedError] = useState<string | null>(null);

    useEffect(() => {
        if (!videoRef.current) return;
        if (!videoSrc) {
            setFeedStatus("idle");
            setFeedError(null);
            return;
        }
        setFeedStatus("loading");
        setFeedError(null);
        videoRef.current.load();
    }, [videoSrc]);

    const feedLabel =
        feedStatus === "loading"
            ? "Connecting to video feed..."
            : feedStatus === "ready"
                ? "Live feed ready"
                : feedStatus === "error"
                    ? "Video feed error"
                    : "Waiting for video source";

    // ── Central command sender (same call the old panel used) ──────────
    const send = async (command: string, value?: number) => {
        if (!droneId) return;
        try {
            setIsSending(true);
            await manualControl({
                droneDbId: droneId,
                command,
                value,
            });
        } catch (err) {
            console.error("Manual control error:", err);
        } finally {
            setIsSending(false);
        }
    };

    // Movement buttons send the same discrete commands the previous panel used
    // (FORWARD / BACKWARD / LEFT / RIGHT), so no backend changes are required.
    const handleMove = (direction: string, command: string) => {
        setActiveDirection(direction);
        void send(command);
        window.setTimeout(() => {
            setActiveDirection((cur) => (cur === direction ? null : cur));
        }, 200);
    };

    // Diagonal taps fire the two adjacent primary commands back-to-back.
    const handleDiagonal = (direction: string, first: string, second: string) => {
        setActiveDirection(direction);
        void send(first);
        void send(second);
        window.setTimeout(() => {
            setActiveDirection((cur) => (cur === direction ? null : cur));
        }, 200);
    };

    // ── Yaw / rotation (compass side buttons, press-and-hold) ──────────
    const rotateHeading = (delta: number) => {
        setHeading((prev) => {
            let next = (prev + delta) % 360;
            if (next < 0) next += 360;
            return next;
        });
    };

    const rotateIntervalRef = useRef<NodeJS.Timeout | null>(null);

    const startRotating = (delta: number, command: string) => {
        if (rotateIntervalRef.current) clearInterval(rotateIntervalRef.current);
        rotateHeading(delta);
        void send(command); // fire the command once at press-down
        rotateIntervalRef.current = setInterval(() => {
            rotateHeading(delta);
        }, 80); // keep the dial smooth locally without flooding the backend
    };

    const stopRotating = () => {
        if (rotateIntervalRef.current) {
            clearInterval(rotateIntervalRef.current);
            rotateIntervalRef.current = null;
        }
    };

    useEffect(() => {
        return () => {
            if (rotateIntervalRef.current) clearInterval(rotateIntervalRef.current);
        };
    }, []);

    // ── Keyboard flight controls ────────────────────────────────────────
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (
                document.activeElement?.tagName === "INPUT" ||
                document.activeElement?.tagName === "TEXTAREA"
            ) {
                return;
            }

            switch (e.key.toLowerCase()) {
                case "arrowup":
                case "w":
                    handleMove("Forward", "FORWARD");
                    break;
                case "arrowdown":
                case "s":
                    handleMove("Backward", "BACKWARD");
                    break;
                case "a":
                    handleMove("Left", "LEFT");
                    break;
                case "d":
                    handleMove("Right", "RIGHT");
                    break;
                case "arrowleft":
                    rotateHeading(-5);
                    void send("YAW_LEFT");
                    break;
                case "arrowright":
                    rotateHeading(5);
                    void send("YAW_RIGHT");
                    break;
            }
        };

        window.addEventListener("keydown", handleKeyDown);
        return () => window.removeEventListener("keydown", handleKeyDown);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [droneId]);

    // ── Drop payload PIN modal ──────────────────────────────────────────
    const [showDropModal, setShowDropModal] = useState(false);
    const [dropPin, setDropPin] = useState("");
    const [dropPinError, setDropPinError] = useState<string | null>(null);
    const [showRecallModal, setShowRecallModal] = useState(false);

    const confirmDropPayload = async () => {
        if (dropPin !== CORRECT_DROP_PIN) {
            setDropPinError("Invalid PIN");
            return;
        }
        setShowDropModal(false);
        setDropPin("");
        setDropPinError(null);
        await send("DROP_PAYLOAD");
    };

    const confirmRecall = async () => {
        setShowRecallModal(false);
        await send("RECALL");
    };

    // ── Flight modes ─────────────────────────────────────────────────────
    const handleModeClick = (mode: FlightMode) => {
        setActiveMode(mode);
        void send(MODE_COMMAND[mode]);
    };

    // ── Altitude dial ────────────────────────────────────────────────────
    const confirmAltitude = async (value: number) => {
        setAltitude(value);
        await send("SET_ALTITUDE", value);
    };

    const header = isPage ? (
        <div className="mb-4 flex items-center justify-between border-b border-neutral-800 pb-4">
            <div className="flex items-center gap-3">
                <button
                    onClick={onClose}
                    className="flex h-9 w-9 items-center justify-center rounded-lg border border-neutral-700 bg-neutral-800/60 text-gray-300 transition-all duration-200 hover:bg-neutral-700 hover:text-white active:scale-95"
                    aria-label="Back to map"
                >
                    ←
                </button>
                <div>
                    <h2 className="text-lg font-semibold text-gray-100">
                        Flight Control Panel{droneName ? ` · ${droneName}` : ""}
                    </h2>
                    <p className="text-xs text-gray-500">Live control for drone {droneId}</p>
                </div>
            </div>

            {typeof socketConnected === "boolean" && (
                <div
                    className={`flex items-center gap-2 rounded-full border px-3 py-1 text-xs ${socketConnected
                            ? "border-emerald-700 bg-emerald-950/40 text-emerald-300"
                            : "border-red-700 bg-red-950/40 text-red-300"
                        }`}
                >
                    <span className={`h-2 w-2 rounded-full ${socketConnected ? "bg-emerald-400" : "bg-red-400"}`} />
                    {socketConnected ? "Live" : "Reconnecting..."}
                </div>
            )}
        </div>
    ) : (
        <div className="mb-3 flex items-start justify-between">
            <div>
                <h2 className="text-lg font-semibold text-gray-100">Flight Control Panel</h2>
                <p className="text-xs text-gray-500">Drag to move · Click to control</p>
            </div>
            <button
                onClick={onClose}
                className="flex h-8 w-8 items-center justify-center rounded-lg border border-neutral-700 bg-neutral-800/60 text-gray-400 transition-all duration-200 hover:bg-neutral-700 hover:text-white active:scale-95"
                aria-label="Close controller"
            >
                ✕
            </button>
        </div>
    );

    const body = (
        <>
            {header}

            {/* TOP SECTION: Live Feed + Status Panel */}
            <div className="flex w-full items-stretch gap-4">
                {/* Live Feed */}
                <div
                    style={{
                        flex: "2 1 0",
                        minHeight: "360px",
                        backgroundColor: "#1a1a1a",
                        borderRadius: "18px",
                        overflow: "hidden",
                        position: "relative",
                    }}
                >
                    <video
                        ref={videoRef}
                        src={videoSrc || undefined}
                        autoPlay
                        muted
                        playsInline
                        style={{
                            width: "100%",
                            height: "100%",
                            objectFit: "cover",
                            display: "block",
                            backgroundColor: "#000",
                        }}
                        onLoadedData={() => {
                            setFeedStatus("ready");
                            setFeedError(null);
                        }}
                        onError={() => {
                            setFeedStatus("error");
                            setFeedError("Unable to load the video feed.");
                        }}
                    />

                    <div
                        style={{
                            position: "absolute",
                            inset: 0,
                            pointerEvents: "none",
                            background:
                                "radial-gradient(circle at center, transparent 45%, rgba(0,0,0,0.35) 100%)",
                        }}
                    />

                    {(feedStatus !== "ready" || feedError) && (
                        <div
                            style={{
                                position: "absolute",
                                inset: 0,
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                padding: "20px",
                                pointerEvents: "none",
                            }}
                        >
                            <div
                                style={{
                                    background: "rgba(0,0,0,0.65)",
                                    borderRadius: "16px",
                                    padding: "16px 18px",
                                    maxWidth: "240px",
                                    color: "#fff",
                                    textAlign: "center",
                                    fontSize: "13px",
                                    lineHeight: 1.5,
                                }}
                            >
                                <strong>{feedLabel}</strong>
                                <div style={{ opacity: 0.78, marginTop: "8px" }}>
                                    {feedError ?? "Prepared for future RTSP/WebRTC integration."}
                                </div>
                            </div>
                        </div>
                    )}

                    <div
                        style={{
                            position: "absolute",
                            top: "8px",
                            left: "12px",
                            fontSize: "11px",
                            color: "rgba(255,255,255,0.4)",
                            letterSpacing: "1px",
                        }}
                    >
                        LIVE
                    </div>

                    <div
                        style={{
                            position: "absolute",
                            top: "8px",
                            right: "12px",
                            fontSize: "11px",
                            color: "rgba(255,255,255,0.7)",
                            fontFamily: "monospace",
                        }}
                    >
                        FPV CAM
                    </div>

                    <div
                        style={{
                            position: "absolute",
                            top: "50%",
                            left: "50%",
                            transform: "translate(-50%, -50%)",
                            width: "60px",
                            height: "60px",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                        }}
                    >
                        <svg viewBox="0 0 60 60" fill="none">
                            <circle cx="30" cy="30" r="20" stroke="white" strokeWidth="1.5" />
                            <line x1="30" y1="5" x2="30" y2="20" stroke="white" strokeWidth="1.5" />
                            <line x1="30" y1="40" x2="30" y2="55" stroke="white" strokeWidth="1.5" />
                            <line x1="5" y1="30" x2="20" y2="30" stroke="white" strokeWidth="1.5" />
                            <line x1="40" y1="30" x2="55" y2="30" stroke="white" strokeWidth="1.5" />
                        </svg>
                    </div>
                </div>

                {/* Status Panel */}
                <div
                    style={{
                        width: "280px",
                        flexShrink: 0,
                        backgroundColor: "#111111",
                        borderRadius: "22px",
                        padding: "18px",
                        display: "flex",
                        flexDirection: "column",
                        gap: "10px",
                        boxShadow: "0 20px 50px rgba(0,0,0,0.25)",
                    }}
                >
                    <div className="flex items-center justify-between">
                        <span style={{ fontSize: "15px", fontWeight: 600 }}>
                            Drone Status: {telemetry?.status === "on_air" ? "FLYING" : (telemetry?.status ?? "UNKNOWN").toString().toUpperCase()}
                        </span>
                        {isSending && <Spinner className="h-4 w-4" />}
                    </div>

                    {/* Mode Buttons Grid */}
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "8px" }}>
                        {FLIGHT_MODES.map((mode) => (
                            <button
                                key={mode}
                                onClick={() => handleModeClick(mode)}
                                style={{
                                    position: "relative",
                                    overflow: "hidden",
                                    background:
                                        activeMode === mode
                                            ? "linear-gradient(180deg, #1d1d1d 0%, #111 100%)"
                                            : "linear-gradient(180deg, #181818 0%, #0f0f0f 100%)",
                                    color: "#ffffff",
                                    border: "1px solid rgba(255,255,255,0.08)",
                                    borderRadius: "10px",
                                    padding: "12px 4px",
                                    fontSize: "13px",
                                    fontWeight: 500,
                                    cursor: "pointer",
                                    transition: "all 0.2s ease",
                                    boxShadow: `
                    inset 0 1px 1px rgba(255,255,255,0.08),
                    inset 0 -4px 10px rgba(0,0,0,0.45),
                    0 4px 12px rgba(0,0,0,0.35)
                  `,
                                    backdropFilter: "blur(6px)",
                                }}
                            >
                                <div
                                    style={{
                                        position: "absolute",
                                        top: 0,
                                        left: "-30%",
                                        width: "80%",
                                        height: "55%",
                                        background:
                                            "linear-gradient(135deg, rgba(255,255,255,0.16), rgba(255,255,255,0.02))",
                                        transform: "skewX(-25deg)",
                                        pointerEvents: "none",
                                        filter: "blur(2px)",
                                    }}
                                />
                                <span style={{ position: "relative", zIndex: 2 }}>{mode}</span>
                            </button>
                        ))}
                    </div>

                    {/* Telemetry Data */}
                    <div style={{ display: "flex", flexDirection: "column", gap: "6px", marginTop: "2px" }}>
                        {[
                            { label: "Latitude", value: telemetry?.lat != null ? telemetry.lat.toFixed(5) : "—" },
                            { label: "Longitude", value: telemetry?.lng != null ? telemetry.lng.toFixed(5) : "—" },
                            { label: "Altitude", value: `${altitude} m` },
                            { label: "Heading", value: `${Math.round(heading)}°` },
                        ].map(({ label, value }) => (
                            <div key={label} style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                                <span style={{ fontSize: "13px", color: "#888888" }}>{label}</span>
                                <span style={{ fontSize: "15px", fontWeight: 400, color: "#ffffff" }}>{value}</span>
                            </div>
                        ))}
                    </div>

                    {/* Drop Payload */}
                    <button
                        onClick={() => {
                            setShowDropModal(true);
                            setDropPin("");
                            setDropPinError(null);
                        }}
                        disabled={isSending}
                        style={{
                            background: "linear-gradient(180deg,#ff1a1a 0%,#ff0000 55%, #e50505 100%)",
                            color: "#ffffff",
                            border: "none",
                            borderRadius: "18px",
                            padding: "12px",
                            fontSize: "14px",
                            fontWeight: 700,
                            cursor: isSending ? "not-allowed" : "pointer",
                            opacity: isSending ? 0.6 : 1,
                            width: "100%",
                        }}
                    >
                        Drop Payload
                    </button>

                    {/* Recall */}
                    <button
                        onClick={() => setShowRecallModal(true)}
                        disabled={isSending}
                        style={{
                            background: "linear-gradient(135deg,#2ecc71,#27ae60)",
                            color: "#ffffff",
                            border: "none",
                            borderRadius: "18px",
                            padding: "12px",
                            fontSize: "14px",
                            fontWeight: 600,
                            cursor: isSending ? "not-allowed" : "pointer",
                            opacity: isSending ? 0.6 : 1,
                            width: "100%",
                        }}
                    >
                        Recall
                    </button>
                </div>
            </div>

            {/* BOTTOM SECTION: Directional Pad + Compass + Altitude */}
            <div
                style={{
                    display: "grid",
                    gridTemplateColumns: "1fr 1fr 1fr",
                    justifyItems: "center",
                    gap: "24px",
                    width: "100%",
                    marginTop: "20px",
                }}
            >
                <DirectionalPad
                    activeDirection={activeDirection}
                    onMove={handleMove}
                    onDiagonal={handleDiagonal}
                />

                <Compass
                    heading={heading}
                    setHeading={(v) => setHeading(v)}
                    startRotating={startRotating}
                    stopRotating={stopRotating}
                    onDragStart={() => {
                        isDraggingCompass.current = true;
                    }}
                    onDragEnd={() => {
                        isDraggingCompass.current = false;
                        void send("SET_HEADING", Math.round(headingRef.current));
                    }}
                />

                <AltitudeControl altitude={altitude} onConfirm={confirmAltitude} />
            </div>

            {/* Drop Payload PIN Modal */}
            {showDropModal && (
                <div
                    style={{
                        position: "fixed",
                        inset: 0,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        background: "rgba(0,0,0,0.6)",
                        zIndex: 10000,
                    }}
                >
                    <div
                        style={{
                            width: "420px",
                            maxWidth: "92%",
                            background: "linear-gradient(180deg,#0f0f10, #0b0b0c)",
                            border: "1px solid rgba(255,255,255,0.06)",
                            borderRadius: "14px",
                            padding: "20px",
                            boxShadow: "0 20px 60px rgba(0,0,0,0.6)",
                            color: "#fff",
                        }}
                    >
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "12px" }}>
                            <div style={{ fontSize: "16px", fontWeight: 700 }}>Confirm Drop Payload</div>
                            <div style={{ color: "rgba(255,255,255,0.45)", fontSize: "12px" }}>Secure</div>
                        </div>

                        <div style={{ fontSize: "13px", color: "rgba(255,255,255,0.8)", marginBottom: "12px" }}>
                            Enter 4-digit PIN to authorize payload release.
                        </div>

                        <input
                            autoFocus
                            value={dropPin}
                            onChange={(e) => {
                                const v = e.target.value.replace(/[^0-9]/g, "").slice(0, 4);
                                setDropPin(v);
                                if (dropPinError) setDropPinError(null);
                            }}
                            onKeyDown={(e) => {
                                if (e.key === "Enter") void confirmDropPayload();
                            }}
                            placeholder="••••"
                            inputMode="numeric"
                            style={{
                                width: "100%",
                                padding: "12px 14px",
                                fontSize: "18px",
                                letterSpacing: "6px",
                                textAlign: "center",
                                borderRadius: "10px",
                                border: "1px solid rgba(255,255,255,0.06)",
                                background: "rgba(255,255,255,0.02)",
                                color: "#fff",
                                marginBottom: "10px",
                            }}
                        />

                        {dropPinError && (
                            <div style={{ color: "#ff6b6b", marginBottom: "10px", fontSize: "13px" }}>{dropPinError}</div>
                        )}

                        <div style={{ display: "flex", gap: "10px", justifyContent: "flex-end" }}>
                            <button
                                onClick={() => {
                                    setShowDropModal(false);
                                    setDropPin("");
                                    setDropPinError(null);
                                }}
                                style={{
                                    padding: "10px 14px",
                                    borderRadius: "10px",
                                    background: "transparent",
                                    border: "1px solid rgba(255,255,255,0.06)",
                                    color: "#fff",
                                    cursor: "pointer",
                                }}
                            >
                                Cancel
                            </button>

                            <button
                                onClick={() => void confirmDropPayload()}
                                disabled={isSending}
                                style={{
                                    padding: "10px 14px",
                                    borderRadius: "10px",
                                    background: "linear-gradient(135deg,#ff4b4b,#ff0000)",
                                    border: "none",
                                    color: "#fff",
                                    cursor: isSending ? "not-allowed" : "pointer",
                                    fontWeight: 700,
                                    opacity: isSending ? 0.6 : 1,
                                }}
                            >
                                {isSending ? "Sending..." : "Confirm"}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Recall confirmation modal */}
            {showRecallModal && (
                <div
                    style={{
                        position: "fixed",
                        inset: 0,
                        background: "rgba(0,0,0,0.6)",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        zIndex: 10000,
                    }}
                >
                    <div
                        style={{
                            background: "#111",
                            padding: "20px",
                            borderRadius: "12px",
                            border: "1px solid rgba(255,255,255,0.1)",
                            width: "320px",
                            textAlign: "center",
                        }}
                    >
                        <h3 style={{ color: "#fff", marginBottom: "10px" }}>Confirm Recall</h3>
                        <p style={{ color: "#aaa", marginBottom: "18px" }}>
                            Are you sure you want the drone to return?
                        </p>
                        <div style={{ display: "flex", gap: "10px", justifyContent: "center" }}>
                            <button
                                onClick={() => setShowRecallModal(false)}
                                style={{
                                    padding: "10px 14px",
                                    background: "#333",
                                    color: "#fff",
                                    border: "none",
                                    borderRadius: "8px",
                                    cursor: "pointer",
                                }}
                            >
                                Cancel
                            </button>
                            <button
                                onClick={() => void confirmRecall()}
                                disabled={isSending}
                                style={{
                                    padding: "10px 14px",
                                    background: "#ff3b3b",
                                    color: "#fff",
                                    border: "none",
                                    borderRadius: "8px",
                                    cursor: isSending ? "not-allowed" : "pointer",
                                    fontWeight: 600,
                                    opacity: isSending ? 0.6 : 1,
                                }}
                            >
                                {isSending ? "Sending..." : "Confirm"}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </>
    );

    if (isPage) {
        return (
            <div className="min-h-screen w-full bg-[#0d0d0d] p-5 text-white sm:p-8">
                <div className="mx-auto w-full max-w-[1150px]">{body}</div>
            </div>
        );
    }

    return (
        <motion.div
            drag
            dragMomentum={false}
            className="fixed z-[9999] w-[min(1150px,95vw)] rounded-3xl border border-neutral-800 bg-[#0d0d0d] p-5 text-white shadow-2xl"
            style={{
                top: "50%",
                left: "50%",
                translateX: "-50%",
                translateY: "-50%",
                maxHeight: "92vh",
                overflowY: "auto",
            }}
        >
            {body}
        </motion.div>
    );
}

