function DPadBtn({
    children,
    top,
    bottom,
    left,
    right,
    translateX,
    translateY,
    center,
    active,
    onClick,
}: {
    children: ReactNode;
    top?: string;
    bottom?: string;
    left?: string;
    right?: string;
    translateX?: string;
    translateY?: string;
    center?: boolean;
    active?: boolean;
    onClick?: () => void;
}) {
    const size = center ? "64px" : "52px";
    const transform = [translateX && `translateX(${translateX})`, translateY && `translateY(${translateY})`]
        .filter(Boolean)
        .join(" ");

    return (
        <button
            onClick={onClick}
            style={{
                position: "absolute",
                top,
                bottom,
                left,
                right,
                width: size,
                height: size,
                borderRadius: "50%",
                background: active
                    ? "linear-gradient(180deg,#ff1a1a 0%,#ff0000 55%, #e50505 100%)"
                    : center
                        ? "#1a1a1a"
                        : "#3a3a3a",
                border: center ? "2px solid rgba(255,255,255,0.1)" : "none",
                cursor: center ? "default" : "pointer",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                transform: transform || undefined,
                zIndex: 2,
                transition: "all 0.2s ease",
            }}
        >
            {children}
        </button>
    );
}

