/* ── COMPASS ── */
function Compass({
    heading,
    setHeading,
    startRotating,
    stopRotating,
    onDragStart,
    onDragEnd,
}: {
    heading: number;
    setHeading: (v: number) => void;
    startRotating: (delta: number, command: string) => void;
    stopRotating: () => void;
    onDragStart: () => void;
    onDragEnd: () => void;
}) {
    const [hoverCCW, setHoverCCW] = useState(false);
    const [hoverCW, setHoverCW] = useState(false);
    const compassRef = useRef<HTMLDivElement | null>(null);
    const isDragging = useRef(false);

    const btnStyle: React.CSSProperties = {
        position: "absolute",
        top: "50%",
        transform: "translateY(-50%)",
        width: "40px",
        height: "40px",
        borderRadius: "50%",
        background: "rgba(25, 25, 25, 0.75)",
        border: "1px solid rgba(255, 255, 255, 0.08)",
        color: "#fff",
        cursor: "pointer",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        transition: "all 0.2s ease",
        zIndex: 10,
        userSelect: "none",
        boxShadow: "0 4px 12px rgba(0,0,0,0.5)",
    };

    const getAngle = (cx: number, cy: number, x: number, y: number) => {
        const dx = x - cx;
        const dy = y - cy;
        let deg = Math.atan2(dy, dx) * (180 / Math.PI);
        deg = (deg + 450) % 360;
        return deg;
    };

    useEffect(() => {
        const handleMove = (e: MouseEvent) => {
            if (!isDragging.current || !compassRef.current) return;
            const rect = compassRef.current.getBoundingClientRect();
            const cx = rect.left + rect.width / 2;
            const cy = rect.top + rect.height / 2;
            setHeading(getAngle(cx, cy, e.clientX, e.clientY));
        };

        const handleUp = () => {
            if (isDragging.current) {
                isDragging.current = false;
                onDragEnd();
            }
        };

        window.addEventListener("mousemove", handleMove);
        window.addEventListener("mouseup", handleUp);
        return () => {
            window.removeEventListener("mousemove", handleMove);
            window.removeEventListener("mouseup", handleUp);
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [setHeading]);

    return (
        <div
            ref={compassRef}
            style={{
                width: "230px",
                height: "230px",
                borderRadius: "50%",
                background: "#111",
                boxShadow: "inset 0 0 20px rgba(255,255,255,0.05)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                position: "relative",
            }}
        >
            <button
                title="Yaw Left"
                onMouseEnter={() => setHoverCCW(true)}
                onMouseLeave={() => {
                    setHoverCCW(false);
                    stopRotating();
                }}
                onMouseDown={() => startRotating(-5, "YAW_LEFT")}
                onMouseUp={stopRotating}
                style={{
                    ...btnStyle,
                    left: "-28px",
                    background: hoverCCW ? "linear-gradient(180deg,#ff1a1a 0%,#ff0000 55%, #e50505 100%)" : "rgba(25, 25, 25, 0.85)",
                }}
            >
                ⟲
            </button>

            <svg viewBox="-20 -20 240 240" width="180" height="180">
                <circle cx="100" cy="100" r="70" stroke="rgba(255,255,255,0.2)" strokeWidth="1" fill="none" />
                {Array.from({ length: 12 }).map((_, i) => {
                    const angle = (i * 30 * Math.PI) / 180;
                    const r1 = i % 3 === 0 ? 75 : 76;
                    const r2 = 94;
                    return (
                        <line
                            key={i}
                            x1={100 + r1 * Math.sin(angle)}
                            y1={100 - r1 * Math.cos(angle)}
                            x2={100 + r2 * Math.sin(angle)}
                            y2={100 - r2 * Math.cos(angle)}
                            stroke="#fff"
                            strokeWidth={3}
                        />
                    );
                })}
                <text x="100" y="-8" textAnchor="middle" fill="white">N</text>
                <text x="100" y="218" textAnchor="middle" fill="white">S</text>
                <text x="-20" y="105" fill="white">W</text>
                <text x="215" y="105" fill="white">E</text>
                <circle cx="100" cy="100" r="22" fill="#1a1a1a" />
                <g stroke="white" strokeWidth="2" strokeLinecap="round" opacity="0.9">
                    <line x1="92" y1="100" x2="108" y2="100" />
                    <line x1="100" y1="92" x2="100" y2="108" />
                </g>
                <polygon
                    points="100,50 104,72 96,72"
                    fill="#ff0b0b"
                    style={{
                        transform: `rotate(${heading}deg)`,
                        transformOrigin: "100px 100px",
                        transition: "transform 0.15s linear",
                        cursor: "grab",
                    }}
                    onMouseDown={(e) => {
                        e.preventDefault();
                        isDragging.current = true;
                        onDragStart();
                    }}
                />
            </svg>

            <button
                title="Yaw Right"
                onMouseEnter={() => setHoverCW(true)}
                onMouseLeave={() => {
                    setHoverCW(false);
                    stopRotating();
                }}
                onMouseDown={() => startRotating(5, "YAW_RIGHT")}
                onMouseUp={stopRotating}
                style={{
                    ...btnStyle,
                    right: "-28px",
                    background: hoverCW ? "linear-gradient(180deg,#ff1a1a 0%,#ff0000 55%, #e50505 100%)" : "rgba(25, 25, 25, 0.85)",
                }}
            >
                ⟳
            </button>
        </div>
    );
}

/* ── ALTITUDE CONTROL ── */
function AltTriUp() {
    return (
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
            <path d="M8 3L14 13H2L8 3Z" fill="white" />
        </svg>
    );
}
function AltTriDown() {
    return (
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
            <path d="M8 13L2 3H14L8 13Z" fill="white" />
        </svg>
    );
}

const LEVELS = Array.from({ length: 41 }, (_, i) => i * 5); // 0,5,...,200
const LINE_WIDTH: Record<number, string> = { 0: "95px", 1: "64px", 2: "36px" };

function AltitudeControl({
    altitude,
    onConfirm,
}: {
    altitude: number;
    onConfirm: (v: number) => void;
}) {
    const [pendingAltitude, setPendingAltitude] = useState<number | null>(null);

    const rawIndex = LEVELS.indexOf(altitude);
    const selectedIndex =
        rawIndex !== -1
            ? rawIndex
            : Math.max(0, LEVELS.findIndex((v) => v >= altitude) !== -1 ? LEVELS.findIndex((v) => v >= altitude) : 0);

    const openConfirm = (newAlt: number) => {
        if (newAlt === altitude) return;
        setPendingAltitude(newAlt);
    };

    const confirmChange = () => {
        if (pendingAltitude === null) return;
        onConfirm(pendingAltitude);
        setPendingAltitude(null);
    };

    const cancelChange = () => setPendingAltitude(null);

    const stepUp = () => {
        const next = selectedIndex + 1;
        if (next < LEVELS.length) openConfirm(LEVELS[next]);
    };
    const stepDown = () => {
        const prev = selectedIndex - 1;
        if (prev >= 0) openConfirm(LEVELS[prev]);
    };

    const wheelAccum = useRef(0);
    const handleWheel = (e: WheelEvent) => {
        e.preventDefault();
        wheelAccum.current += e.deltaY;
        if (wheelAccum.current > 30) {
            wheelAccum.current = 0;
            stepUp();
        } else if (wheelAccum.current < -30) {
            wheelAccum.current = 0;
            stepDown();
        }
    };

    const lastTouch = useRef<number | null>(null);
    const handleTouchStart = (e: TouchEvent) => {
        lastTouch.current = e.touches[0].clientY;
    };
    const handleTouchMove = (e: TouchEvent) => {
        if (lastTouch.current === null) return;
        const dy = lastTouch.current - e.touches[0].clientY;
        if (Math.abs(dy) > 18) {
            dy > 0 ? stepUp() : stepDown();
            lastTouch.current = e.touches[0].clientY;
        }
    };

    const visibleItems = Array.from({ length: 5 }, (_, i) => {
        const lvlIdx = selectedIndex - 2 + i;
        return lvlIdx >= 0 && lvlIdx < LEVELS.length ? LEVELS[lvlIdx] : null;
    });

    return (
        <>
            <div
                onWheel={handleWheel}
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                style={{
                    width: "230px",
                    height: "230px",
                    borderRadius: "50%",
                    backgroundColor: "#111",
                    border: "2px solid rgba(255,255,255,0.08)",
                    boxShadow: "inset 0 0 20px rgba(255,255,255,0.05)",
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    justifyContent: "space-between",
                    padding: "14px 0",
                    flexShrink: 0,
                    userSelect: "none",
                    cursor: "ns-resize",
                }}
            >
                <button
                    onClick={stepUp}
                    disabled={selectedIndex === LEVELS.length - 1}
                    style={{
                        width: "44px",
                        height: "44px",
                        borderRadius: "50%",
                        backgroundColor: "#3a3a3a",
                        border: "none",
                        cursor: selectedIndex === LEVELS.length - 1 ? "default" : "pointer",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        opacity: selectedIndex === LEVELS.length - 1 ? 0.3 : 1,
                    }}
                >
                    <AltTriUp />
                </button>

                <div style={{ display: "flex", flexDirection: "column", gap: "4px", alignItems: "center", width: "100%", padding: "0 16px", boxSizing: "border-box" }}>
                    {visibleItems.map((lvl, i) => {
                        const isCenter = i === 2;
                        const offset = Math.abs(i - 2);
                        const lineW = LINE_WIDTH[offset];
                        if (lvl === null) return <div key={`empty-${i}`} style={{ height: "24px", width: "100%" }} />;
                        return (
                            <div
                                key={lvl}
                                onClick={() => {
                                    if (!isCenter) openConfirm(lvl);
                                }}
                                style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "16px", width: "100%", cursor: isCenter ? "default" : "pointer" }}
                            >
                                <div style={{ width: lineW, height: isCenter ? "2px" : "1px", backgroundColor: isCenter ? "#ffffff" : "rgba(255,255,255,0.25)" }} />
                                <span style={{ width: "40px", textAlign: "center", fontSize: isCenter ? "15px" : "14px", fontWeight: isCenter ? 600 : 400, color: isCenter ? "#ffffff" : "rgba(255,255,255,0.32)" }}>
                                    {lvl}
                                </span>
                                <div style={{ width: lineW, height: isCenter ? "2px" : "1px", backgroundColor: isCenter ? "#ffffff" : "rgba(255,255,255,0.25)" }} />
                            </div>
                        );
                    })}
                </div>

                <button
                    onClick={stepDown}
                    disabled={selectedIndex === 0}
                    style={{
                        width: "44px",
                        height: "44px",
                        borderRadius: "50%",
                        backgroundColor: "#3a3a3a",
                        border: "none",
                        cursor: selectedIndex === 0 ? "default" : "pointer",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        opacity: selectedIndex === 0 ? 0.3 : 1,
                    }}
                >
                    <AltTriDown />
                </button>
            </div>

            {pendingAltitude !== null && (
                <div
                    style={{
                        position: "fixed",
                        inset: 0,
                        background: "rgba(0,0,0,0.6)",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        zIndex: 10000,
                    }}
                >
                    <div style={{ background: "#111", padding: "20px", borderRadius: "12px", border: "1px solid rgba(255,255,255,0.1)", width: "280px", textAlign: "center" }}>
                        <h3 style={{ color: "#fff", marginBottom: "10px" }}>Confirm Altitude Change</h3>
                        <p style={{ color: "#aaa", marginBottom: "16px" }}>
                            Change altitude to <b style={{ color: "#fff" }}>{pendingAltitude}</b>?
                        </p>
                        <div style={{ display: "flex", gap: "10px", justifyContent: "center" }}>
                            <button onClick={cancelChange} style={{ padding: "8px 12px", background: "#333", color: "#fff", border: "none", borderRadius: "6px", cursor: "pointer" }}>
                                Cancel
                            </button>
                            <button onClick={confirmChange} style={{ padding: "8px 12px", background: "#ff3b3b", color: "#fff", border: "none", borderRadius: "6px", cursor: "pointer" }}>
                                Confirm
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}